// Some schedule entries carry the base code inside a longer label
// (e.g. "22CSG59 - Lab", "LA/PD-22CSE554", "22CSA581/582/583").
// This resolves any entry.code back to a known subject icon.
function getSubjectIcon(code) {
  for (const known of Object.keys(SUBJECT_ICONS)) {
    if (code.includes(known)) return SUBJECT_ICONS[known];
  }
  if (code.includes("581/582/583")) return SUBJECT_ICONS["22CSA582"];
  return null;
}

const SUBJECT_INITIALS = {
  "22CS51": "CN",
  "22CS52": "TOC",
  "22CSL54": "CN LAB",
  "22CSE552": "5G",
  "22CSE553": "EH",
  "22CSE554": "DSP",
  "22CSE555": "DevOps",
  "22CSE556": "IoT",
  "22CSE557": "QM",
  "22RM57": "RM",
  "22CSA581": "MATLAB",
  "22CSA582": "UI/UX LAB",
  "22CSA583": "TBST Lab",
  "22CSG59": "COMP STATS",
  "22IPC5": "IPC",
};

function slotSpan(entry) {
  const first = TIME_SLOTS.find((s) => s.id === entry.slots[0]);
  const last = TIME_SLOTS.find((s) => s.id === entry.slots[entry.slots.length - 1]);
  return `${first.start} - ${last.end}`;
}

function toMinutes(t) {
  const [h, m] = t.split(":").map(Number);
  const hour24 = h === 12 ? 12 : h < 9 ? h + 12 : h;
  return hour24 * 60 + m;
}

function daysUntil(dateStr) {
  if (!dateStr) return null;
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const due = new Date(dateStr + "T00:00:00");
  return Math.round((due - today) / 86400000);
}

function urgencyStyle(daysLeft) {
  if (daysLeft === null) return { fill: "var(--surface-1)", border: "var(--border)", text: "var(--text-secondary)", label: "No date" };
  if (daysLeft < 0) return { fill: "#FCEBEB", border: "#E24B4A", text: "#791F1F", label: "Overdue" };
  if (daysLeft === 0) return { fill: "#FAEEDA", border: "#BA7517", text: "#633806", label: "Due today" };
  if (daysLeft <= 7) return { fill: "#FAEEDA", border: "#BA7517", text: "#633806", label: `${daysLeft}d left` };
  return { fill: "#F1EFE8", border: "#B4B2A9", text: "#5F5E5A", label: `${daysLeft}d left` };
}

function formatLocalDate(d) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

function weekDatesFrom(now) {
  const jsDay = now.getDay();
  const mondayOffset = (jsDay + 6) % 7;
  const monday = new Date(now);
  monday.setDate(now.getDate() - mondayOffset);
  const map = {};
  DAYS.forEach((day, i) => {
    const d = new Date(monday);
    d.setDate(monday.getDate() + i);
    map[day] = formatLocalDate(d);
  });
  return map;
}

const MONTH_NAMES = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

function inferFullDate(day, month) {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const dayNum = parseInt(day, 10);
  const monthNum = parseInt(month, 10);
  let candidate = new Date(today.getFullYear(), monthNum - 1, dayNum);
  if (candidate < today) {
    candidate = new Date(today.getFullYear() + 1, monthNum - 1, dayNum);
  }
  return formatLocalDate(candidate);
}

function TimetableApp() {
  const [names, setNames] = useState({});
  const [loaded, setLoaded] = useState(false);
  const [editingCode, setEditingCode] = useState(null);
  const [draftName, setDraftName] = useState("");
  const [now, setNow] = useState(new Date());
  const [reminders, setReminders] = useState([]);
  const [todoOpen, setTodoOpen] = useState(false);
  const [history, setHistory] = useState([]);
  const [historyOpen, setHistoryOpen] = useState(false);
  const [showAddReminder, setShowAddReminder] = useState(false);
  const [newTitle, setNewTitle] = useState("");
  const [newDay, setNewDay] = useState("");
  const [newMonth, setNewMonth] = useState("");
  const [wantsDate, setWantsDate] = useState(false);
  const [formError, setFormError] = useState("");

  const todayName = JS_DAY_TO_NAME[now.getDay()];
  const defaultDay = DAYS.includes(todayName) ? todayName : "Monday";
  const [selectedDay, setSelectedDay] = useState(defaultDay);

  useEffect(() => {
    const timer = setInterval(() => setNow(new Date()), 60000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    (async () => {
      try {
        const result = await window.storage.get("subject-names", false);
        if (result && result.value) setNames(JSON.parse(result.value));
      } catch (e) {
        // no saved names yet
      }
      try {
        const result = await window.storage.get("reminders", false);
        if (result && result.value) setReminders(JSON.parse(result.value));
      } catch (e) {
        // no saved reminders yet
      }
      try {
        const result = await window.storage.get("todo-history", false);
        if (result && result.value) setHistory(JSON.parse(result.value));
      } catch (e) {
        // no history yet
      }
      setLoaded(true);
    })();
  }, []);

  const saveReminders = async (updated) => {
    setReminders(updated);
    try {
      await window.storage.set("reminders", JSON.stringify(updated), false);
    } catch (e) {
      console.error("Could not save reminders", e);
    }
  };

  const saveHistory = async (updated) => {
    setHistory(updated);
    try {
      await window.storage.set("todo-history", JSON.stringify(updated), false);
    } catch (e) {
      console.error("Could not save history", e);
    }
  };

  const logHistory = async (entry) => {
    const updated = [entry, ...history].slice(0, 200);
    await saveHistory(updated);
  };

  const clearHistory = async () => {
    await saveHistory([]);
  };

  const addReminder = async () => {
    if (!newTitle.trim()) {
      setFormError("Enter a task first");
      return;
    }
    if (wantsDate && (!newDay || !newMonth)) {
      setFormError("Pick a day and month, or turn off the due date toggle");
      return;
    }
    const updated = [
      ...reminders,
      { id: Date.now().toString(), title: newTitle.trim(), dueDate: wantsDate ? inferFullDate(newDay, newMonth) : null, done: false },
    ];
    await saveReminders(updated);
    setNewTitle("");
    setNewDay("");
    setNewMonth("");
    setWantsDate(false);
    setFormError("");
    setShowAddReminder(false);
  };

  const deleteReminder = async (id) => {
    const target = reminders.find((r) => r.id === id);
    if (target) {
      await logHistory({
        id: `del-${target.id}-${Date.now()}`,
        title: target.title,
        action: "deleted",
        at: new Date().toISOString(),
      });
    }
    await saveReminders(reminders.filter((r) => r.id !== id));
  };

  const toggleDone = async (id) => {
    const target = reminders.find((r) => r.id === id);
    const nowDone = target ? !target.done : false;
    if (target && nowDone) {
      await logHistory({
        id: `done-${target.id}-${Date.now()}`,
        title: target.title,
        action: "completed",
        at: new Date().toISOString(),
      });
    }
    await saveReminders(reminders.map((r) => (r.id === id ? { ...r, done: !r.done } : r)));
  };

  const tomorrowJsIndex = (now.getDay() + 1) % 7;
  const tomorrowName = JS_DAY_TO_NAME[tomorrowJsIndex];
  const tomorrowEntries = DAYS.includes(tomorrowName)
    ? RAW_SCHEDULE[tomorrowName].filter((e) => e.type !== "free")
    : [];
  const tomorrowLabs = tomorrowEntries.filter((e) => e.type === "lab");

  const sortedReminders = [...reminders].sort((a, b) => {
    if (a.done !== b.done) return a.done ? 1 : -1;
    const aDays = daysUntil(a.dueDate);
    const bDays = daysUntil(b.dueDate);
    if (aDays === null && bDays === null) return 0;
    if (aDays === null) return 1;
    if (bDays === null) return -1;
    return aDays - bDays;
  });

  const weekDates = weekDatesFrom(now);
  const selectedDayDate = weekDates[selectedDay];
  const dueOnSelectedDay = reminders.filter((r) => r.dueDate === selectedDayDate && !r.done);
  const daysWithDueItems = new Set(reminders.filter((r) => !r.done && r.dueDate).map((r) => r.dueDate));

  const [notifStatus, setNotifStatus] = useState(
    typeof Notification !== "undefined" ? Notification.permission : "unsupported"
  );

  const enableNotifications = async () => {
    if (typeof Notification === "undefined") return;
    const result = await Notification.requestPermission();
    setNotifStatus(result);
  };

  const notifiedRef = useRef({});
  useEffect(() => {
    (async () => {
      try {
        const result = await window.storage.get("notified-log", false);
        if (result && result.value) notifiedRef.current = JSON.parse(result.value);
      } catch (e) {
        // no log yet
      }
    })();
  }, []);

  const markNotified = async (key) => {
    notifiedRef.current[key] = true;
    try {
      await window.storage.set("notified-log", JSON.stringify(notifiedRef.current), false);
    } catch (e) {
      console.error("Could not save notification log", e);
    }
  };

  const fireNotification = (title, body) => {
    if (typeof Notification === "undefined" || Notification.permission !== "granted") return;
    new Notification(title, { body });
  };

  useEffect(() => {
    if (notifStatus !== "granted") return;
    const check = () => {
      const dateKey = now.toISOString().slice(0, 10);
      const nowMins = now.getHours() * 60 + now.getMinutes();

      const todayEntries = RAW_SCHEDULE[todayName] || [];
      todayEntries.forEach((entry) => {
        if (entry.type === "free") return;
        const first = TIME_SLOTS.find((s) => s.id === entry.slots[0]);
        const startMins = toMinutes(first.start);
        const key = `class-${entry.code}-${dateKey}-${first.start}`;
        if (!notifiedRef.current[key] && startMins - nowMins <= 10 && startMins - nowMins >= 0) {
          fireNotification(
            `${names[entry.code] || SUBJECT_INITIALS[entry.code] || entry.code} starts soon`,
            `Starts at ${first.start} today`
          );
          markNotified(key);
        }
      });

      // Rule 1: day before a lab, around 7pm, remind about record & observation
      if (tomorrowLabs.length > 0 && now.getHours() >= 19) {
        const key = `lab-record-${dateKey}`;
        if (!notifiedRef.current[key]) {
          fireNotification(
            "CK have you written your record and observation",
            `Lab tomorrow (${tomorrowName}): ${tomorrowLabs.map((e) => names[e.code] || SUBJECT_INITIALS[e.code] || e.code).join(", ")}`
          );
          markNotified(key);
        }
      }

      // Rule 2: to-do items with a due date get reminded on both the 2-days-before
      // and 1-day-before mark, once per day, with a fixed message.
      reminders.forEach((r) => {
        if (r.done || !r.dueDate) return;
        const daysLeft = daysUntil(r.dueDate);
        if (daysLeft === 2 || daysLeft === 1) {
          const key = `submission-${r.id}-${dateKey}`;
          if (!notifiedRef.current[key]) {
            fireNotification(
              "NiGx you've got submission to do",
              `${r.title} — due ${new Date(r.dueDate + "T00:00:00").toLocaleDateString([], { weekday: "short", month: "short", day: "numeric" })}`
            );
            markNotified(key);
          }
        } else if (daysLeft === 0 || daysLeft < 0) {
          const key = `reminder-${r.id}-${dateKey}`;
          if (!notifiedRef.current[key]) {
            fireNotification(
              daysLeft < 0 ? `Overdue: ${r.title}` : `Due today: ${r.title}`,
              "Tap to open your timetable app"
            );
            markNotified(key);
          }
        }
      });
    };
    check();
    const interval = setInterval(check, 60000);
    return () => clearInterval(interval);
  }, [notifStatus, now, reminders, names]);

  const saveName = async (code, name) => {
    const updated = { ...names, [code]: name };
    setNames(updated);
    try {
      await window.storage.set("subject-names", JSON.stringify(updated), false);
    } catch (e) {
      console.error("Could not save name", e);
    }
  };

  const nowMinutes = now.getHours() * 60 + now.getMinutes();
  const isToday = selectedDay === todayName;
  const entries = RAW_SCHEDULE[selectedDay];

  const openEditor = (code) => {
    setEditingCode(code);
    setDraftName(names[code] || "");
  };

  const closeEditor = () => setEditingCode(null);

  const confirmEditor = async () => {
    const trimmed = draftName.trim();
    await saveName(editingCode, trimmed);
    setEditingCode(null);
  };

  if (!loaded) {
    return <div style={{ padding: "2rem 0", textAlign: "center", color: "var(--text-muted)" }}>Loading your timetable...</div>;
  }

  return (
    <div
      className="tt-app"
      style={{
        "--surface-1": "#FFFBF2",
        "--surface-2": "#F4E7D3",
        "--text-primary": "#211D17",
        "--text-secondary": "#6E6151",
        "--text-muted": "#A5967E",
        "--text-danger": "#B23A2E",
        "--border": "#211D17",
        "--accent": "#EA6A3C",
        "--accent-text": "#FFFBF2",
        "--font-mono": "'JetBrains Mono', 'Courier New', monospace",
        fontFamily: "'Poppins', 'Segoe UI', sans-serif",
        background: "#F2E6D2",
        color: "var(--text-primary)",
        padding: "18px",
        borderRadius: "24px",
      }}
    >
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;600&display=swap');
        .tt-app button {
          font-family: 'Poppins', sans-serif;
          font-weight: 600;
          background: var(--surface-1);
          color: var(--text-primary);
          border: 2px solid var(--border);
          border-radius: 12px;
          padding: 8px 14px;
          cursor: pointer;
        }
        .tt-app button:hover { transform: translateY(-1px); }
        .tt-app input[type="text"],
        .tt-app select {
          font-family: 'Poppins', sans-serif;
          background: var(--surface-1);
          color: var(--text-primary);
          border: 2px solid var(--border);
          border-radius: 12px;
          padding: 8px 10px;
        }
        .tt-app .tt-cta {
          background: var(--accent) !important;
          color: var(--accent-text) !important;
          border: 2px solid var(--border) !important;
        }
      `}</style>

      <h1 className="sr-only" style={{ position: "absolute", width: 1, height: 1, overflow: "hidden" }}>
        V(A) semester class timetable
      </h1>

      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: "16px",
          background: "var(--surface-1)",
          border: "2px solid var(--border)",
          borderRadius: "18px",
          padding: "14px 16px",
        }}
      >
        <div>
          <p style={{ fontSize: "12px", fontWeight: 600, letterSpacing: "0.06em", textTransform: "uppercase", color: "var(--text-secondary)", margin: 0 }}>V(A) semester</p>
          <p style={{ fontSize: "22px", fontWeight: 800, margin: "2px 0 0" }}>{selectedDay}{isToday ? " · Today" : ""}</p>
        </div>
        <p
          style={{
            fontSize: "13px",
            fontWeight: 600,
            color: "var(--accent-text)",
            background: "var(--accent)",
            border: "2px solid var(--border)",
            borderRadius: "999px",
            padding: "6px 12px",
            margin: 0,
          }}
        >
          {now.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" })}
        </p>
      </div>

      <div style={{ marginBottom: "12px" }}>
        <div style={{ display: "flex", gap: "8px", alignItems: "stretch" }}>
          <button
            onClick={() => setTodoOpen(!todoOpen)}
            style={{
              flex: 1,
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              background: "var(--surface-1)",
              border: "2px solid var(--border)",
              borderRadius: todoOpen ? "18px 18px 0 0" : "18px",
              padding: "10px 12px",
            }}
          >
            <span style={{ fontSize: "14px", fontWeight: 500 }}>
              To-do list
              {sortedReminders.filter((r) => !r.done).length > 0 && (
                <span style={{ color: "var(--text-secondary)", fontWeight: 400 }}>
                  {" "}
                  ({sortedReminders.filter((r) => !r.done).length})
                </span>
              )}
            </span>
            <i
              className="ti ti-chevron-down"
              aria-hidden="true"
              style={{ fontSize: "18px", transform: todoOpen ? "rotate(180deg)" : "none" }}
            ></i>
          </button>
          <button
            onClick={() => setHistoryOpen(!historyOpen)}
            aria-label="View to-do history"
            title="To-do history"
            style={{
              flexShrink: 0,
              width: "44px",
              height: "44px",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              background: historyOpen ? "var(--accent)" : "var(--surface-1)",
              border: "2px solid var(--border)",
              borderRadius: "999px",
              padding: 0,
              overflow: "hidden",
            }}
          >
            <img
              src={HISTORY_ICON}
              alt=""
              style={{
                width: "100%",
                height: "100%",
                objectFit: "cover",
                borderRadius: "999px",
                opacity: historyOpen ? 0.9 : 1,
              }}
            />
          </button>
        </div>

        {historyOpen && (
          <div
            style={{
              marginTop: "8px",
              background: "var(--surface-1)",
              border: "2px solid var(--border)",
              borderRadius: "18px",
              padding: "12px",
            }}
          >
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "8px" }}>
              <p style={{ margin: 0, fontSize: "13px", fontWeight: 700 }}>To-do history</p>
              {history.length > 0 && (
                <button onClick={clearHistory} style={{ fontSize: "12px", padding: "4px 10px" }}>
                  Clear
                </button>
              )}
            </div>
            {history.length === 0 && (
              <p style={{ fontSize: "13px", color: "var(--text-muted)", margin: 0 }}>
                Completed and deleted tasks will show up here.
              </p>
            )}
            {history.map((h) => (
              <div
                key={h.id}
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  gap: "8px",
                  padding: "8px 0",
                  borderBottom: "1px dashed var(--border)",
                }}
              >
                <div>
                  <p style={{ margin: 0, fontSize: "13px", fontWeight: 500 }}>{h.title}</p>
                  <p style={{ margin: "2px 0 0", fontSize: "11px", color: "var(--text-muted)" }}>
                    {new Date(h.at).toLocaleString([], { dateStyle: "medium", timeStyle: "short" })}
                  </p>
                </div>
                <span
                  style={{
                    fontSize: "10px",
                    fontWeight: 700,
                    textTransform: "uppercase",
                    letterSpacing: "0.04em",
                    color: h.action === "completed" ? "#3F6B4F" : "var(--text-danger)",
                    background: h.action === "completed" ? "#DDE7DC" : "#FCEBEB",
                    border: `2px solid ${h.action === "completed" ? "#3F6B4F" : "#E24B4A"}`,
                    borderRadius: "999px",
                    padding: "3px 8px",
                    flexShrink: 0,
                  }}
                >
                  {h.action === "completed" ? "Done" : "Deleted"}
                </span>
              </div>
            ))}
          </div>
        )}

        {todoOpen && (
          <div
            style={{
              border: "2px solid var(--border)",
              borderTop: "none",
              borderRadius: "0 0 18px 18px",
              padding: "12px",
            }}
          >
            <div style={{ display: "flex", justifyContent: "flex-end", marginBottom: showAddReminder ? "10px" : 0 }}>
              <button onClick={() => setShowAddReminder(!showAddReminder)} style={{ fontSize: "13px", padding: "6px 10px" }}>
                <i className="ti ti-plus" aria-hidden="true" style={{ marginRight: "4px", fontSize: "14px" }}></i>
                Add
              </button>
            </div>

            {showAddReminder && (
              <div style={{ background: "var(--surface-2)", borderRadius: "18px", padding: "20px", marginBottom: "20px", border: "2px solid var(--border)" }}>
                <input
                  type="text"
                  value={newTitle}
                  onChange={(e) => setNewTitle(e.target.value)}
                  placeholder="e.g. DBMS assignment 2"
                  style={{ width: "100%", marginBottom: "8px" }}
                />
                <label style={{ display: "flex", alignItems: "center", gap: "8px", fontSize: "13px", color: "var(--text-secondary)", marginBottom: "8px" }}>
                  <input type="checkbox" checked={wantsDate} onChange={(e) => setWantsDate(e.target.checked)} />
                  Set a submission date
                </label>
                {wantsDate && (
                  <div style={{ display: "flex", gap: "8px", marginBottom: "8px" }}>
                    <select value={newDay} onChange={(e) => setNewDay(e.target.value)} style={{ flex: 1 }}>
                      <option value="">Day</option>
                      {Array.from({ length: 31 }, (_, i) => i + 1).map((d) => (
                        <option key={d} value={d}>{d}</option>
                      ))}
                    </select>
                    <select value={newMonth} onChange={(e) => setNewMonth(e.target.value)} style={{ flex: 1 }}>
                      <option value="">Month</option>
                      {MONTH_NAMES.map((m, i) => (
                        <option key={m} value={i + 1}>{m}</option>
                      ))}
                    </select>
                  </div>
                )}
                {formError && (
                  <p style={{ fontSize: "13px", color: "var(--text-danger)", margin: "0 0 8px" }}>{formError}</p>
                )}
                <div style={{ display: "flex", gap: "8px" }}>
                  <button onClick={addReminder} className="tt-cta" style={{ flex: 1 }}>Save</button>
                  <button
                    onClick={() => { setShowAddReminder(false); setFormError(""); setWantsDate(false); setNewDay(""); setNewMonth(""); }}
                    style={{ flex: 1 }}
                  >
                    Cancel
                  </button>
                </div>
              </div>
            )}

            {sortedReminders.length === 0 && !showAddReminder && (
              <p style={{ fontSize: "13px", color: "var(--text-muted)" }}>
                Nothing on your list yet. Add a task, with or without a submission date.
              </p>
            )}

            {sortedReminders.map((r) => {
              const daysLeft = daysUntil(r.dueDate);
              const style = urgencyStyle(daysLeft);
              return (
                <div
                  key={r.id}
                  style={{
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                    gap: "8px",
                    background: r.done ? "var(--surface-2)" : style.fill,
                    border: r.done ? "2px solid var(--border)" : `2px solid ${style.border}`,
                    borderRadius: "18px",
                    padding: "10px 12px",
                    marginBottom: "8px",
                    opacity: r.done ? 0.6 : 1,
                  }}
                >
                  <div style={{ display: "flex", alignItems: "flex-start", gap: "10px" }}>
                    <input
                      type="checkbox"
                      checked={r.done}
                      onChange={() => toggleDone(r.id)}
                      aria-label={`Mark ${r.title} as done`}
                      style={{ marginTop: "3px" }}
                    />
                    <div>
                      <p
                        style={{
                          margin: 0,
                          fontSize: "14px",
                          fontWeight: 500,
                          color: r.done ? "var(--text-secondary)" : style.text,
                          textDecoration: r.done ? "line-through" : "none",
                        }}
                      >
                        {r.title}
                      </p>
                      <p style={{ margin: "2px 0 0", fontSize: "12px", color: r.done ? "var(--text-muted)" : style.text, opacity: 0.85 }}>
                        {r.dueDate
                          ? new Date(r.dueDate + "T00:00:00").toLocaleDateString([], { weekday: "short", month: "short", day: "numeric" })
                          : "No date"}
                        {" · "}
                        {style.label}
                      </p>
                    </div>
                  </div>
                  <button
                    onClick={() => deleteReminder(r.id)}
                    aria-label={`Delete ${r.title}`}
                    style={{ padding: "6px 8px", flexShrink: 0 }}
                  >
                    <i className="ti ti-trash" aria-hidden="true" style={{ fontSize: "15px" }}></i>
                  </button>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {notifStatus === "default" && (
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            gap: "8px",
            background: "var(--surface-1)",
            border: "2px solid var(--border)",
            borderRadius: "18px",
            padding: "10px 12px",
            marginBottom: "12px",
          }}
        >
          <p style={{ margin: 0, fontSize: "13px", color: "var(--text-secondary)" }}>
            Turn on notifications for classes and deadlines
          </p>
          <button onClick={enableNotifications} className="tt-cta" style={{ fontSize: "13px", padding: "6px 10px", flexShrink: 0 }}>
            Enable
          </button>
        </div>
      )}
      {notifStatus === "denied" && (
        <div
          style={{
            background: "var(--surface-1)",
            border: "2px solid var(--border)",
            borderRadius: "18px",
            padding: "10px 12px",
            marginBottom: "12px",
          }}
        >
          <p style={{ margin: 0, fontSize: "13px", color: "var(--text-secondary)" }}>
            Notifications are blocked. Allow them in your browser's site settings to get alerts.
          </p>
        </div>
      )}

      {tomorrowEntries.length > 0 && (
        <div
          style={{
            background: tomorrowLabs.length > 0 ? "#FCEBEB" : "var(--surface-1)",
            border: tomorrowLabs.length > 0 ? "2px solid #E24B4A" : "2px solid var(--border)",
            borderRadius: "18px",
            padding: "10px 12px",
            marginBottom: "12px",
          }}
        >
          <p style={{ margin: 0, fontSize: "13px", fontWeight: 500, color: tomorrowLabs.length > 0 ? "#791F1F" : "var(--text-primary)" }}>
            {tomorrowLabs.length > 0
              ? `${tomorrowName} has ${tomorrowLabs.length === 1 ? "a lab" : `${tomorrowLabs.length} labs`} — plan ahead`
              : `${tomorrowName}'s schedule is ready`}
          </p>
          <p style={{ margin: "4px 0 0", fontSize: "12px", color: tomorrowLabs.length > 0 ? "#791F1F" : "var(--text-secondary)" }}>
            {tomorrowEntries.map((e) => names[e.code] || SUBJECT_INITIALS[e.code] || e.code).join(", ")}
          </p>
        </div>
      )}

      <div style={{ display: "flex", gap: "6px", overflowX: "auto", paddingBottom: "10px", marginBottom: "8px" }}>
        {DAYS.map((day) => {
          const active = day === selectedDay;
          const today = day === todayName;
          const hasDue = daysWithDueItems.has(weekDates[day]);
          return (
            <button
              key={day}
              onClick={() => setSelectedDay(day)}
              style={{
                flexShrink: 0,
                position: "relative",
                padding: "8px 16px",
                borderRadius: "999px",
                fontSize: "13px",
                fontWeight: 700,
                background: active ? "var(--accent)" : "var(--surface-1)",
                color: active ? "var(--accent-text)" : "var(--text-primary)",
                border: "2px solid var(--border)",
              }}
            >
              {day.slice(0, 3)}
              {today ? " •" : ""}
              {hasDue && (
                <span
                  style={{
                    position: "absolute",
                    top: "2px",
                    right: "2px",
                    width: "6px",
                    height: "6px",
                    borderRadius: "50%",
                    background: "#E24B4A",
                  }}
                />
              )}
            </button>
          );
        })}
      </div>

      <div>
        {dueOnSelectedDay.length > 0 && (
          <div style={{ marginBottom: "10px" }}>
            {dueOnSelectedDay.map((r) => (
              <div
                key={r.id}
                style={{
                  display: "flex",
                  gap: "10px",
                  marginBottom: "8px",
                }}
              >
                <span style={{ fontSize: "11px", color: "var(--text-muted)", width: "72px", flexShrink: 0, paddingTop: "12px" }}>
                  Due
                </span>
                <div
                  style={{
                    flex: 1,
                    background: "#FCEBEB",
                    border: "2px solid #E24B4A",
                    borderRadius: "18px",
                    padding: "10px 12px",
                  }}
                >
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: "8px" }}>
                    <p style={{ margin: 0, fontSize: "14px", fontWeight: 500, color: "#791F1F" }}>{r.title}</p>
                    <span style={{ fontSize: "11px", color: "#791F1F", whiteSpace: "nowrap", flexShrink: 0 }}>Submission</span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
        {TIME_SLOTS.map((slot) => {
          if (slot.kind === "break") {
            return (
              <div
                key={slot.id}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: "10px",
                  padding: "4px 0",
                  margin: "2px 0",
                }}
              >
                <span style={{ fontSize: "11px", color: "var(--text-muted)", width: "72px", flexShrink: 0 }}>
                  {slot.start}
                </span>
                <div style={{ flex: 1, borderTop: "1px dashed var(--border)", position: "relative" }}>
                  <span
                    style={{
                      position: "absolute",
                      top: "-8px",
                      left: "8px",
                      background: "var(--surface-2)",
                      padding: "0 6px",
                      fontSize: "11px",
                      color: "var(--text-muted)",
                    }}
                  >
                    {slot.label}
                  </span>
                </div>
              </div>
            );
          }

          const entry = entries.find((e) => e.slots.includes(slot.id));
          if (!entry) return null;
          const isFirstSlotOfEntry = entry.slots[0] === slot.id;
          if (!isFirstSlotOfEntry) return null;

          const style = TYPE_STYLE[entry.type];
          const displayName = names[entry.code] || SUBJECT_INITIALS[entry.code] || entry.code;
          const showCodeSubtitle = entry.type !== "free" && displayName !== entry.code;
          const span = slotSpan(entry);

          const first = TIME_SLOTS.find((s) => s.id === entry.slots[0]);
          const last = TIME_SLOTS.find((s) => s.id === entry.slots[entry.slots.length - 1]);
          const currentlyOn =
            isToday && entry.type !== "free" && nowMinutes >= toMinutes(first.start) && nowMinutes < toMinutes(last.end);

          return (
            <div key={entry.code + slot.id} style={{ display: "flex", gap: "10px", marginBottom: "8px" }}>
              <span style={{ fontSize: "11px", color: "var(--text-muted)", width: "72px", flexShrink: 0, paddingTop: "12px" }}>
                {slot.start}
              </span>
              <button
                onClick={() => entry.type !== "free" && openEditor(entry.code)}
                style={{
                  flex: 1,
                  textAlign: "left",
                  background: style.fill,
                  border: currentlyOn ? `2px solid ${style.border}` : `2px solid ${style.border}`,
                  borderRadius: "18px",
                  padding: "10px 12px",
                  cursor: entry.type === "free" ? "default" : "pointer",
                }}
              >
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: "8px" }}>
                  <div>
                    <p style={{ margin: 0, fontSize: "14px", fontWeight: 500, color: style.text }}>
                      {entry.type === "free" ? "Free period" : displayName}
                    </p>
                    {showCodeSubtitle && (
                      <p style={{ margin: "2px 0 0", fontSize: "11px", fontFamily: "var(--font-mono)", color: style.text, opacity: 0.75 }}>
                        {entry.code}
                      </p>
                    )}
                  </div>
                  <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end", gap: "4px", flexShrink: 0 }}>
                    <span style={{ fontSize: "11px", color: style.text, whiteSpace: "nowrap" }}>
                      {style.label}
                    </span>
                    {entry.type !== "free" && getSubjectIcon(entry.code) && (
                      <img
                        src={getSubjectIcon(entry.code)}
                        alt=""
                        style={{
                          width: "26px",
                          height: "26px",
                          borderRadius: "999px",
                          border: "2px solid var(--border)",
                          objectFit: "cover",
                        }}
                      />
                    )}
                  </div>
                </div>
                <p style={{ margin: "6px 0 0", fontSize: "11px", color: style.text, opacity: 0.85 }}>{span}</p>
                {currentlyOn && (
                  <p style={{ margin: "4px 0 0", fontSize: "11px", fontWeight: 500, color: style.text }}>
                    Happening now
                  </p>
                )}
              </button>
            </div>
          );
        })}
      </div>

      {editingCode && (
        <div
          style={{
            position: "static",
            marginTop: "16px",
            background: "var(--surface-1)",
            borderRadius: "20px",
            padding: "1rem",
            border: "2px solid var(--border)",
          }}
        >
          <p style={{ fontSize: "13px", color: "var(--text-secondary)", margin: "0 0 4px" }}>
            Rename <span style={{ fontFamily: "var(--font-mono)" }}>{editingCode}</span>
          </p>
          <input
            type="text"
            value={draftName}
            onChange={(e) => setDraftName(e.target.value)}
            placeholder="e.g. Data Structures"
            style={{ width: "100%", marginBottom: "10px" }}
            autoFocus
          />
          <div style={{ display: "flex", gap: "8px" }}>
            <button onClick={confirmEditor} className="tt-cta" style={{ flex: 1 }}>Save</button>
            <button onClick={closeEditor} style={{ flex: 1 }}>Cancel</button>
          </div>
        </div>
      )}
    </div>
  );
}
